body:
async ({ input }) => {
      const delivered = await notifyOwner(input);
      return {
        success: delivered,
      } as const;
    }

async ({ input, ctx }) => {
      const jobIds = await queueTranslation({
        ...input,
        userId: ctx.user.id,
      });
      return { success: true, jobIds, count: jobIds.length };
    }

async ({ input }) => {
      return getEntityTranslations(
        input.entityType,
        input.entityId,
        input.languageCode,
        input.fieldNames
      );
    }

async ({ input }) => {
      return getBatchTranslations(
        input.entityType,
        input.entityIds,
        input.languageCode,
        input.fieldNames
      );
    }

async ({ input, ctx }) => {
      // Only owner, admin, or maintenance_manager can manually override
      const allowedRoles = ["owner", "admin", "maintenance_manager", "general_maintenance_manager", "construction_procurement_manager"];
      if (!allowedRoles.includes(ctx.user.role)) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "ليس لديك صلاحية لتعديل الترجمات يدوياً",
        });
      }

      await manualOverrideTranslation(
        input.entityType,
        input.entityId,
        input.fieldName,
        input.languageCode,
        input.translatedText,
        ctx.user.id
      );
      return { success: true };
    }

async ({ input }) => {
      return getTranslationVersions(
        input.entityType,
        input.entityId,
        input.fieldName,
        input.languageCode
      );
    }

async ({ input, ctx }) => {
      // Only owner/admin can retry
      if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
        throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك يمكنه إعادة المحاولة" });
      }
      const count = await retryFailedJobs(input?.entityType);
      return { success: true, retriedCount: count };
    }

async () => {
    return getTranslationStats();
  }

async ({ input }) => {
      return getTranslationJobsList(input || undefined);
    }

async ({ input, ctx }) => {
      await updateUserLanguage(ctx.user.id, input.language);
      return { success: true };
    }

async () => {
    return ENTITY_FIELD_MAP;
  }

opts => {
    if (opts.ctx.authFailure === "dependency") {
      throw new TRPCError({
        code: "INTERNAL_SERVER_ERROR",
        message: AUTH_TEMPORARILY_UNAVAILABLE_ERR_MSG,
      });
    }
    return opts.ctx.user;
  }

({ ctx }) => {
    const cookieOptions = getSessionCookieOptions(ctx.req);
    ctx.res.clearCookie(COOKIE_NAME, { ...cookieOptions, maxAge: -1 });
    return { success: true } as const;
  }

async ({ input, ctx }) => {
    const user = await db.getUserByUsername(input.username);
    if (!user || !user.passwordHash) {
      throw new TRPCError({ code: "UNAUTHORIZED", message: "اسم المستخدم أو كلمة المرور غير صحيحة" });
    }
    if (!user.isActive) {
      throw new TRPCError({ code: "FORBIDDEN", message: "الحساب معطل" });
    }
    const valid = await bcrypt.compare(input.password, user.passwordHash);
    if (!valid) {
      throw new TRPCError({ code: "UNAUTHORIZED", message: "اسم المستخدم أو كلمة المرور غير صحيحة" });
    }
    const sessionToken = await sdk.createSessionToken(user.openId, { name: user.name || user.username || "", expiresInMs: 1000 * 60 * 60 * 24 * 365 });
    const cookieOptions = getSessionCookieOptions(ctx.req);
    ctx.res.cookie(COOKIE_NAME, sessionToken, { ...cookieOptions, maxAge: 1000 * 60 * 60 * 24 * 365 });
    await db.updateLastSignedIn(user.openId);
    const twoFactorSecret = await db.getTwoFactorSecret(user.id);
    const twoFactorEnforcementStatus = getTwoFactorEnforcementStatus(user, twoFactorSecret?.isEnabled || false);

    return {
      success: true,
      user: { id: user.id, name: user.name, role: user.role, username: user.username },
      twoFactorEnforcementStatus
    };
  }

async ({ input, ctx }) => {
    if (ctx.user.passwordHash && input.currentPassword) {
      const valid = await bcrypt.compare(input.currentPassword, ctx.user.passwordHash);
      if (!valid) throw new TRPCError({ code: "UNAUTHORIZED", message: "كلمة المرور الحالية غير صحيحة" });
    }
    const hash = await bcrypt.hash(input.newPassword, 10);
    await db.updateUserPassword(ctx.user.id, hash);
    return { success: true };
  }

async ({ ctx }) => {
    const rows = await cacheManager.getOrCompute(
      cacheKeys.users(),
      () => db.getAllUsers(),
      600 // 10 minutes
    );
    return localizeNamedRecords("USER", rows as any[], (ctx.user.preferredLanguage || "ar") as any);
  }

async ({ input, ctx }) => {
    const rows = await cacheManager.getOrCompute(
      cacheKeys.usersByRole(input.role),
      () => db.getUsersByRole(input.role),
      600 // 10 minutes
    );
    return localizeNamedRecords("USER", rows as any[], (ctx.user.preferredLanguage || "ar") as any);
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك يمكنه تغيير الأدوار" });
    }
    const oldUser = await db.getUserById(input.userId);
    await db.updateUserRole(input.userId, input.role);
    await db.createAuditLog({ userId: ctx.user.id, action: "update_role", entityType: "user", entityId: input.userId, oldValues: { role: oldUser?.role }, newValues: { role: input.role } });
    // Invalidate user cache
    invalidateCache.users();
    return { success: true };
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك يمكنه تعديل المستخدمين" });
    }
    const oldUser = await db.getUserById(input.id);
    if (!oldUser) throw new TRPCError({ code: "NOT_FOUND", message: "المستخدم غير موجود" });
    const { id, ...updateData } = input;
    await db.updateUser(id, updateData);
    if (updateData.name?.trim()) {
      const sourceLanguage = await detectLanguage(updateData.name);
      void queueTranslation({ entityType: "USER", entityId: id, fields: [{ fieldName: "name", text: updateData.name.trim() }], sourceLanguage, userId: ctx.user.id })
        .catch((error) => console.error("[USER] name re-translation queue failed:", error));
    }
    await db.createAuditLog({ userId: ctx.user.id, action: "update_user", entityType: "user", entityId: id, oldValues: { name: oldUser.name, email: oldUser.email, role: oldUser.role }, newValues: updateData });
    invalidateCache.users();
    return { success: true };
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك أو المسؤول يمكنه رفع التوقيع" });
    }
    const oldUser = await db.getUserById(input.userId);
    if (!oldUser) throw new TRPCError({ code: "NOT_FOUND", message: "المستخدم غير موجود" });
    await db.updateUser(input.userId, { signatureUrl: input.signatureUrl } as any);
    await db.createAuditLog({
      userId: ctx.user.id,
      action: input.signatureUrl ? "upload_signature" : "remove_signature",
      entityType: "user",
      entityId: input.userId,
      oldValues: { signatureUrl: (oldUser as any).signatureUrl ?? null },
      newValues: { signatureUrl: input.signatureUrl },
    });
    invalidateCache.users();
    return { success: true };
  }

async ({ input, ctx }) => {
    // دور "مستودع" مسموح له بالإضافة فقط (بدون تعديل/حذف/تغيير أدوار — مقيّدة بباقي الدوال أدناه)
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin" && ctx.user.role !== "warehouse") {
      throw new TRPCError({ code: "FORBIDDEN", message: "ليس لديك صلاحية إنشاء مستخدمين" });
    }
    const existing = await db.getUserByUsername(input.username);
    if (existing) throw new TRPCError({ code: "CONFLICT", message: "اسم المستخدم موجود مسبقاً" });
    const hash = await bcrypt.hash(input.password, 10);
    const id = await db.createLocalUser({ ...input, passwordHash: hash });
    if (id && input.name.trim()) {
      const sourceLanguage = await detectLanguage(input.name);
      void queueTranslation({ entityType: "USER", entityId: id, fields: [{ fieldName: "name", text: input.name.trim() }], sourceLanguage, userId: ctx.user.id })
        .catch((error) => console.error("[USER] name translation queue failed:", error));
    }
    await db.createAuditLog({ userId: ctx.user.id, action: "create_user", entityType: "user", entityId: id!, newValues: { username: input.username, name: input.name, role: input.role } });
    invalidateCache.users();
    return { success: true, id };
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "ليس لديك صلاحية" });
    }
    const hash = await bcrypt.hash(input.newPassword, 10);
    await db.updateUserPassword(input.userId, hash);
    await db.createAuditLog({ userId: ctx.user.id, action: "reset_password", entityType: "user", entityId: input.userId });
    return { success: true };
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك يمكنه حذف المستخدمين" });
    }
    // التحقق من كلمة مرور المدير
    if (!ctx.user.passwordHash) {
      throw new TRPCError({ code: "FORBIDDEN", message: "لا يمكن التحقق من هويتك (حساب OAuth)" });
    }
    const validPassword = await bcrypt.compare(input.confirmPassword, ctx.user.passwordHash);
    if (!validPassword) {
      throw new TRPCError({ code: "UNAUTHORIZED", message: "كلمة المرور غير صحيحة" });
    }
    const user = await db.getUserById(input.id);
    if (!user) throw new TRPCError({ code: "NOT_FOUND", message: "المستخدم غير موجود" });
    if (user.role === "owner") throw new TRPCError({ code: "FORBIDDEN", message: "لا يمكن حذف المالك" });
    await db.deleteUser(input.id);
    await db.createAuditLog({ userId: ctx.user.id, action: "delete_user", entityType: "user", entityId: input.id, oldValues: { name: user.name, email: user.email, role: user.role } });
    invalidateCache.users();
    return { success: true };
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك يمكنه تعطيل/تفعيل المستخدمين" });
    }
    const user = await db.getUserById(input.id);
    if (!user) throw new TRPCError({ code: "NOT_FOUND", message: "المستخدم غير موجود" });
    if (user.role === "owner") throw new TRPCError({ code: "FORBIDDEN", message: "لا يمكن تعطيل المالك" });
    await db.toggleUserActive(input.id, input.isActive);
    await db.createAuditLog({ userId: ctx.user.id, action: input.isActive ? "activate_user" : "deactivate_user", entityType: "user", entityId: input.id });
    invalidateCache.users();
    return { success: true };
  }

async ({ ctx }) => {
    const rows = await cacheManager.getOrCompute(
      cacheKeys.usersByRole("technician"),
      () => db.getUsersByRole("technician"),
      600 // 10 minutes
    );
    return localizeNamedRecords("USER", rows as any[], (ctx.user.preferredLanguage || "ar") as any);
  }

async ({ input, ctx }) => {
    if (ctx.user.role !== "owner" && ctx.user.role !== "admin") {
      throw new TRPCError({ code: "FORBIDDEN", message: "فقط المالك يمكنه تعديل التخصص" });
    }
    const { userId, ...specialtyData } = input;
    await db.updateUser(userId, specialtyData);
    invalidateCache.users();
    return { success: true };
  }

async ({ ctx }) => {
    const rows = await cacheManager.getOrCompute(
      cacheKeys.sites(),
      () => db.getAllSites(),
      600 // 10 minutes
    );
    return localizeNamedRecords("SITE", rows as any[], (ctx.user.preferredLanguage || "ar") as any);
  }

async ({ input, ctx }) => {
    // Auto-translate name
    let nameAr: string | undefined;
    let nameEn: string | undefined;
    let nameUr: string | undefined;
    try {
      const translations = await translateFields({ name: input.name });
      nameAr = translations.name?.ar;
      nameEn = translations.name?.en;
      nameUr = translations.name?.ur;
    } catch (e) { /* fallback */ }
    const id = await db.createSite({ ...input, nameEn, nameUr });
    if (id) {
      await Promise.all([
        nameAr && storeCompletedEntityTranslation("SITE", id, "name", "ar", nameAr),
        nameEn && storeCompletedEntityTranslation("SITE", id, "name", "en", nameEn),
        nameUr && storeCompletedEntityTranslation("SITE", id, "name", "ur", nameUr),
      ]);
    }
    await db.createAuditLog({ userId: ctx.user.id, action: "create_site", entityType: "site", entityId: id!, newValues: input });
    // Invalidate sites cache
    invalidateCache.sites();
    return { id };
  }

async ({ input, ctx }) => {
    const oldSite = await db.getSiteById(input.id);
    if (!oldSite) throw new TRPCError({ code: "NOT_FOUND", message: "الموقع غير موجود" });
    const { id, ...updateData } = input;
    // Auto-translate name if changed
    let siteExtraFields: { nameEn?: string; nameUr?: string } = {};
    let translatedNames: { ar?: string; en?: string; ur?: string } = {};
    if (updateData.name) {
      try {
        const translations = await translateFields({ name: updateData.name });
        translatedNames = translations.name || {};
        siteExtraFields.nameEn = translations.name?.en;
        siteExtraFields.nameUr = translations.name?.ur;
      } catch (e) { /* fallback */ }
    }
    await db.updateSite(id, { ...updateData, ...siteExtraFields });
    if (updateData.name) {
      await Promise.all([
        translatedNames.ar && storeCompletedEntityTranslation("SITE", id, "name", "ar", translatedNames.ar),
        translatedNames.en && storeCompletedEntityTranslation("SITE", id, "name", "en", translatedNames.en),
        translatedNames.ur && storeCompletedEntityTranslation("SITE", id, "name", "ur", translatedNames.ur),
      ]);
    }
    await db.createAuditLog({ userId: ctx.user.id, action: "update_site", entityType: "site", entityId: id, oldValues: { name: oldSite.name, address: oldSite.address, description: oldSite.description }, newValues: updateData });
    // Invalidate sites cache
    invalidateCache.sites();
    return { success: true };
  }

async ({ input, ctx }) => {
    const site = await db.getSiteById(input.id);
    if (!site) throw new TRPCError({ code: "NOT_FOUND", message: "الموقع غير موجود" });
    await db.deleteSite(input.id);
    await db.createAuditLog({ userId: ctx.user.id, action: "delete_site", entityType: "site", entityId: input.id, oldValues: { name: site.name, address: site.address } });
    // Invalidate sites cache
    invalidateCache.sites();
    return { success: true };
  }

async ({ input, ctx }) => {
    const rows = await db.getSections(input?.siteId);
    return localizeNamedRecords("SECTION", rows as any[], (ctx.user.preferredLanguage || "ar") as any);
  }

async ({ input, ctx }) => {
    // Auto-translate name
    let sectionNameAr: string | undefined;
    let sectionNameEn: string | undefined;
    let sectionNameUr: string | undefined;
    try {
      const translations = await translateFields({ name: input.name });
      sectionNameAr = translations.name?.ar;
      sectionNameEn = translations.name?.en;
      sectionNameUr = translations.name?.ur;
    } catch (e) { /* fallback */ }
    const id = await db.createSection({ ...input, nameEn: sectionNameEn, nameUr: sectionNameUr, isActive: true });
    if (id) {
      await Promise.all([
        sectionNameAr && storeCompletedEntityTranslation("SECTION", id, "name", "ar", sectionNameAr),
        sectionNameEn && storeCompletedEntityTranslation("SECTION", id, "name", "en", sectionNameEn),
        sectionNameUr && storeCompletedEntityTranslation("SECTION", id, "name", "ur", sectionNameUr),
      ]);
    }
    await db.createAuditLog({ userId: ctx.user.id, action: "create_section", entityType: "section", entityId: id!, newValues: input });
    return { id };
  }

async ({ input, ctx }) => {
    const { id, ...updateData } = input;
    let sectionExtraFields: { nameEn?: string; nameUr?: string } = {};
    let translatedNames: { ar?: string; en?: string; ur?: string } = {};
    if (updateData.name) {
      try {
        const translations = await translateFields({ name: updateData.name });
        translatedNames = translations.name || {};
        sectionExtraFields.nameEn = translations.name?.en;
        sectionExtraFields.nameUr = translations.name?.ur;
      } catch (e) { /* fallback */ }
    }
    await db.updateSection(id, { ...updateData, ...sectionExtraFields });
    if (updateData.name) {
      await Promise.all([
        translatedNames.ar && storeCompletedEntityTranslation("SECTION", id, "name", "ar", translatedNames.ar),
        translatedNames.en && storeCompletedEntityTranslation("SECTION", id, "name", "en", translatedNames.en),
        translatedNames.ur && storeCompletedEntityTranslation("SECTION", id, "name", "ur", translatedNames.ur),
      ]);
    }
    await db.createAuditLog({ userId: ctx.user.id, action: "update_section", entityType: "section", entityId: id, newValues: updateData });
    return { success: true };
  }

async ({ input, ctx }) => {
    await db.deleteSection(input.id);
    await db.createAuditLog({ userId: ctx.user.id, action: "delete_section", entityType: "section", entityId: input.id });
    return { success: true };
  }

async ({ input }) => {
    return db.getAllTechnicians(input?.activeOnly ?? false);
  }

async ({ input, ctx }) => {
    // Auto-translate name and specialty
    let techNameEn: string | undefined;
    let techNameUr: string | undefined;
    let techSpecialtyEn: string | undefined;
    let techSpecialtyUr: string | undefined;
    try {
      const fieldsToTranslate: Record<string, string> = { name: input.name };
      if (input.specialty) fieldsToTranslate.specialty = input.specialty;
      const translations = await translateFields(fieldsToTranslate);
      techNameEn = translations.name?.en;
      techNameUr = translations.name?.ur;
      techSpecialtyEn = translations.specialty?.en;
      techSpecialtyUr = translations.specialty?.ur;
    } catch (e) { /* fallback */ }
    const id = await db.createTechnician({ ...input, nameEn: techNameEn, nameUr: techNameUr, specialtyEn: techSpecialtyEn, specialtyUr: techSpecialtyUr });
    await db.createAuditLog({ userId: ctx.user.id, action: "create_technician", entityType: "technician", entityId: id!, newValues: input });
    return { id };
  }

async ({ input, ctx }) => {
    const { id, ...updateData } = input;
    let techExtraFields: { nameEn?: string; nameUr?: string; specialtyEn?: string; specialtyUr?: string } = {};
    if (updateData.name || updateData.specialty) {
      try {
        const fieldsToTranslate: Record<string, string> = {};
        if (updateData.name) fieldsToTranslate.name = updateData.name;
        if (updateData.specialty) fieldsToTranslate.specialty = updateData.specialty;
        const translations = await translateFields(fieldsToTranslate);
        if (updateData.name) { techExtraFields.nameEn = translations.name?.en; techExtraFields.nameUr = translations.name?.ur; }
        if (updateData.specialty) { techExtraFields.specialtyEn = translations.specialty?.en; techExtraFields.specialtyUr = translations.specialty?.ur; }
      } catch (e) { /* fallback */ }
    }
    await db.updateTechnician(id, { ...updateData, ...techExtraFields });
    await db.createAuditLog({ userId: ctx.user.id, action: "update_technician", entityType: "technician", entityId: id, newValues: updateData });
    return { success: true };
  }

async ({ input, ctx }) => {
    await db.deleteTechnician(input.id);
    await db.createAuditLog({ userId: ctx.user.id, action: "delete_technician", entityType: "technician", entityId: input.id });
    return { success: true };
  }

async () => {
    return db.getTechnicianOpenTicketCounts();
  }

async ({ ctx, input }) => {
    assertTeam(ctx.user);
    await assertActiveItUser(ctx.user.id);
    await db.withTransaction(async tx => {
      // Same lock ordering for claim, transfer and promotion: parent, department, tasks.
      await db.lockTicketForSubTicketSequence(input.ticketId, tx);
      await db.lockTicketDepartmentForTaskSequence(input.departmentId, tx);
      const parent = await db.getTicketById(input.ticketId, tx);
      const department = await db.getTicketDepartmentById(input.departmentId, tx);
      if (!parent || !department || department.ticketId !== input.ticketId) fail("الجهة لا تنتمي لهذا البلاغ");
      if (!canClaimItDepartment(ctx.user, parent, department)) throw new TRPCError({ code: "CONFLICT", message: "البلاغ مستلم بالفعل أو لم يعد متاحًا للاستلام" });
      const result = await tx.update(ticketDepartments).set({ claimedById: ctx.user.id, claimedAt: new Date().toISOString().slice(0,19).replace("T", " "), status: "active" })
        .where(and(eq(ticketDepartments.id, department.id), isNull(ticketDepartments.claimedById)));
      if (result[0].affectedRows !== 1) throw new TRPCError({ code: "CONFLICT", message: "استلم عضو آخر البلاغ" });
      if (parent.maintenanceResponsibleDepartment === DEPT.IT) {
        await db.updateTicket(parent.id, { assignedToId: ctx.user.id, assignedAt: new Date() }, tx);
        await db.syncSingleTicketItem(parent.id, { assignedToId: ctx.user.id, assignedAt: new Date() }, tx);
      }
      await audit(tx, ctx.user.id, parent.id, "claim_it_ticket", { departmentId: department.id, claimedById: ctx.user.id });
    });
    return { success: true };
  }

async ({ ctx, input }) => {
    assertTeam(ctx.user);
    if (input.userId) await assertActiveItUser(input.userId);
    await db.withTransaction(async tx => {
      await db.lockTicketForSubTicketSequence(input.ticketId, tx);
      await db.lockTicketDepartmentForTaskSequence(input.departmentId, tx);
      const parent = await db.getTicketById(input.ticketId, tx);
      const department = await db.getTicketDepartmentById(input.departmentId, tx);
      if (!parent || !department || department.ticketId !== parent.id || department.department !== DEPT.IT) fail("جهة غير صالحة");
      if (["closed", "requester_confirmed"].includes(parent.status)) fail("البلاغ مغلق");
      if (department.claimedById !== ctx.user.id && !(ctx.user.role === APP_ROLE.IT_MANAGER && department.responsibleManagerId === ctx.user.id)) throw new TRPCError({ code: "FORBIDDEN" });
      await db.updateTicketDepartment(department.id, { claimedById: input.userId, claimedAt: input.userId ? new Date() : null }, tx);
      if (parent.maintenanceResponsibleDepartment === DEPT.IT) {
        await db.updateTicket(parent.id, { assignedToId: input.userId, assignedAt: input.userId ? new Date() : null }, tx);
        await db.syncSingleTicketItem(parent.id, { assignedToId: input.userId, assignedAt: input.userId ? new Date() : null }, tx);
      }
      await audit(tx, ctx.user.id, parent.id, "handover_it_ticket", { from: department.claimedById, to: input.userId, reason: input.reason });
    });
    return { success: true };
  }

async ({ ctx, input }) => {
    if (![APP_ROLE.GENERAL_MAINTENANCE_MANAGER, APP_ROLE.CONSTRUCTION_PROCUREMENT_MANAGER, APP_ROLE.MAINTENANCE_MANAGER, APP_ROLE.OWNER, APP_ROLE.ADMIN].includes(ctx.user.role as any)) throw new TRPCError({ code: "FORBIDDEN" });
    const manager = await getItManager();
    let number = "";
    await db.withTransaction(async tx => {
      await db.lockTicketForSubTicketSequence(input.ticketId, tx);
      const ticket = await db.getTicketById(input.ticketId, tx);
      if (!ticket) fail("البلاغ غير موجود");
      assertTicketWorkflowManageable(ctx.user, ticket);
      if (ticket.maintenanceResponsibleDepartment && ![DEPT.GENERAL, DEPT.CONSTRUCTION].includes(ticket.maintenanceResponsibleDepartment as any)) {
        fail("هذا التحويل مخصص لبلاغات الصيانة العامة أو الإنشاءات");
      }
      if (!["pending_triage", "department_planning", "under_inspection"].includes(ticket.status) || ticket.maintenancePath || ticket.sourceTaskId) fail("التحويل متاح قبل بدء التنفيذ واختيار المسار فقط");
      if (ticket.inspectionNotes || ticket.inspectionSubmittedAt || ticket.inspectionApprovedAt) fail("توجد نتيجة فحص؛ لا يمكن نقل مسؤولية البلاغ بهذه المرحلة");
      const departments = await db.getTicketDepartments(ticket.id, tx);
      if (departments.length > 1) fail("البلاغ متعدد الجهات؛ يجب تحويل جهة مستقلة قبل تنفيذها");
      const tasks = await db.getTicketTasks(ticket.id, tx);
      if (tasks.some((t: any) => t.convertedTicketId || ["promoted", "completed"].includes(t.status))) fail("لا يمكن التحويل بعد إنشاء بلاغات فرعية");
      // Historical or manually linked PO data must not be orphaned by routing.
      const orders = await tx.execute(sql`SELECT id FROM purchase_orders WHERE ticketId = ${ticket.id} LIMIT 1`);
      if (orders[0]?.length) fail("يوجد طلب شراء مرتبط؛ لا يمكن التحويل");
      const items = await db.getTicketItems(ticket.id, tx);
      if (items.length > 1 || items.some((i: any) => i.maintenancePath)) fail("البلاغ يتضمن بنود تنفيذ مستقلة؛ لا يمكن تحويل الرأس بالكامل");
      if (departments[0]) {
        await db.lockTicketDepartmentForTaskSequence(departments[0].id, tx);
        await db.updateTicketDepartment(departments[0].id, { department: DEPT.IT, responsibleManagerId: manager.id, claimedById: null, claimedAt: null, routedById: ctx.user.id, routedAt: new Date(), routingNote: input.reason, status: "planning" }, tx);
      } else await db.createTicketDepartments([{ ticketId: ticket.id, department: DEPT.IT, responsibleManagerId: manager.id, routedById: ctx.user.id, routingNote: input.reason, status: "planning" }], tx);
      for (const task of tasks) {
        await db.replaceTicketTaskAssignees(task.id, [], ctx.user.id, tx);
        if (task.status !== "cancelled") await db.updateTicketTask(task.id, { status: "pending_assignment" }, tx);
      }
      const change = { status: "department_planning", workflowModel: "department_tasks", maintenanceResponsibleDepartment: DEPT.IT, maintenanceResponsibleManagerId: manager.id, maintenanceRoutedById: ctx.user.id, maintenanceRoutedAt: new Date(), maintenanceRoutingNote: input.reason, assignedToId: null, assignedTechnicianId: null, assignedAt: null, inspectionWorkflowStatus: null };
      await db.updateTicket(ticket.id, change, tx);
      const itemChange = { responsibleDepartment: DEPT.IT, responsibleManagerId: manager.id, status: "department_planning", assignedToId: null, assignedTechnicianId: null, assignedAt: null, routedById: ctx.user.id, routingNote: input.reason };
      if (items.length) await db.syncSingleTicketItem(ticket.id, itemChange, tx);
      else await db.createTicketItem({ ticketId: ticket.id, itemNumber: 1, title: ticket.title, isLegacySingleItem: 1, createdById: ctx.user.id, ...itemChange }, tx);
      await audit(tx, ctx.user.id, ticket.id, "route_maintenance_ticket_to_it", { reason: input.reason, previousDepartment: ticket.maintenanceResponsibleDepartment, managerId: manager.id });
      number = ticket.ticketNumber;
    });
    await db.addTicketStatusHistory({ ticketId: input.ticketId, toStatus: "department_planning", changedById: ctx.user.id, notes: `تحويل إلى فريق تقنية المعلومات: ${input.reason}` });
    await notifyItTeamArrival(input.ticketId, number);
    return { success: true };
  }

async ({ ctx, input }) => {
