    const allInWarehouse = activeItemsWH.length > 0 && activeItemsWH.every(i => ["delivered_to_warehouse", "delivered_to_requester"].includes(i.status));
    if (allInWarehouse) {
      await db.updatePurchaseOrder(item.purchaseOrderId, { status: "received" });
