      const actionLabel = actionMode === "purchase"
        ? (poStatus === "partial_purchase" ? "إكمال الشراء" : "تنفيذ الشراء")
        : (item.status === "estimated" ? "جاهز للإرسال" : "بانتظار التسعير");

