        const existing = existingRows[0] as any;
        if (!existing) throw new TRPCError({ code: "NOT_FOUND", message: "التصنيف غير موجود" });

        // تغيير كود عقدة منفردة يكسر أكواد الأبناء والأصناف. منذ إضافة إعادة
